items = _items

CAPACITY = 400

servers = []
seen_servers = set()

total_meetings = 0
total_participants = 0
active_servers = 0
unavailable_servers = 0


def get_number(value):
    if isinstance(value, dict):
        value = value.get("#text", 0)
    try:
        return int(value)
    except (ValueError, TypeError):
        return 0


def get_meetings(data):
    response = data.get("response", data)

    if not isinstance(response, dict):
        return None

    returncode = response.get("returncode")

    if isinstance(returncode, dict):
        returncode = returncode.get("#text")

    if returncode is not None and str(returncode).upper() != "SUCCESS":
        return None

    meetings_data = response.get("meetings", {})

    if not isinstance(meetings_data, dict):
        return []

    meetings = meetings_data.get("meeting", [])

    if isinstance(meetings, dict):
        return [meetings]

    if isinstance(meetings, list):
        return meetings

    return []


def load_indicator(load):
    # 10 сегментів = 100%
    filled = max(0, min(10, round(load / 10)))
    empty = 10 - filled

    bar = "▰" * filled + "▱" * empty

    if load < 50:
        color = "🟢"
    elif load < 80:
        color = "🟡"
    else:
        color = "🔴"

    return f"{color} {bar}"


for item in items:
    data = item["json"]

    name = str(
        data.get("server_name")
        or data.get("server")
        or data.get("name")
        or "BBB"
    ).strip()

    # Не додаємо один сервер двічі
    if name in seen_servers:
        continue

    seen_servers.add(name)

    status = str(data.get("status", "")).lower()

    if status == "unavailable" or data.get("error"):
        servers.append({
            "name": name,
            "available": False
        })
        continue

    if "total_meetings" in data or "total_participants" in data:
        meetings_count = get_number(
            data.get("total_meetings", 0)
        )
        participants = get_number(
            data.get("total_participants", 0)
        )
    else:
        meetings = get_meetings(data)

        if meetings is None:
            servers.append({
                "name": name,
                "available": False
            })
            continue

        meetings_count = len(meetings)

        participants = sum(
            get_number(m.get("participantCount", 0))
            for m in meetings
            if isinstance(m, dict)
        )

    servers.append({
        "name": name,
        "available": True,
        "meetings": meetings_count,
        "participants": participants
    })


def sort_key(server):
    name = server["name"]
    number = name.replace("BBB", "")

    try:
        return int(number)
    except (ValueError, TypeError):
        return 9999


lines = ["📊 BBB Monitor — звіт", ""]

for server in sorted(servers, key=sort_key):
    name = server["name"]

    if not server["available"]:
        unavailable_servers += 1

        lines.append(f"🖥 {name} — 🔴 Недоступний")
        lines.append("━━━━━━━━━━━━━━")
        lines.append("")
        continue

    meetings_count = server["meetings"]
    participants = server["participants"]

    active_servers += 1
    total_meetings += meetings_count
    total_participants += participants

    load = participants / CAPACITY * 100

    lines.append(f"🖥 {name} — 🟢 Працює")
    lines.append(
        f"🎥 Активних конференцій: {meetings_count}"
    )
    lines.append(
        f"👥 Учасників онлайн: {participants} / {CAPACITY}"
    )
    lines.append(f"📈 Завантаженість: {load:.1f}%")
    lines.append(load_indicator(load))
    lines.append("━━━━━━━━━━━━━━")
    lines.append("")


total_capacity = active_servers * CAPACITY

total_load = (
    total_participants / total_capacity * 100
    if total_capacity else 0
)

lines.append("📌 ЗАГАЛЬНИЙ ПІДСУМОК")
lines.append(f"🟢 Доступних серверів: {active_servers}")
lines.append(f"🔴 Недоступних серверів: {unavailable_servers}")
lines.append(f"🎥 Активних конференцій: {total_meetings}")
lines.append(
    f"👥 Учасників онлайн: {total_participants} / {total_capacity}"
)
lines.append(
    f"📈 Загальна завантаженість: {total_load:.1f}%"
)

if active_servers > 0:
    lines.append(load_indicator(total_load))

report = "\n".join(lines)

return [{
    "json": {
        "report": report,
        "text": report
    }
}]

