const history = $input.first().json;

const earliestDate = String(history.earliest_date || '');
const latestDate = String(history.latest_date || '');

const datePattern = /^\d{4}-\d{2}-\d{2}$/;

if (
  !datePattern.test(earliestDate) ||
  !datePattern.test(latestDate)
) {
  throw new Error(
    'Не отримано earliest_date або latest_date з BBB History Dates'
  );
}

if (earliestDate > latestDate) {
  throw new Error('Некоректний діапазон історії BBB');
}

// Поточна дата за Києвом
const today = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Europe/Kyiv',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

// Верхня межа календаря
const maxDate = latestDate < today ? latestDate : today;

if (earliestDate > maxDate) {
  throw new Error('Немає доступних дат історії BBB');
}

// Відкриваємо останній доступний місяць
const [year, month] = maxDate.split('-').map(Number);

const [minYear, minMonth] = earliestDate.split('-').map(Number);
const [maxYear, maxMonth] = maxDate.split('-').map(Number);

const pad = value => String(value).padStart(2, '0');

// Доступність стрілок
const canGoPrev =
  year > minYear ||
  (year === minYear && month > minMonth);

const canGoNext =
  year < maxYear ||
  (year === maxYear && month < maxMonth);

// Кількість днів
const daysInMonth = new Date(year, month, 0).getDate();

// Понеділок = 0
const firstDay =
  (new Date(year, month - 1, 1).getDay() + 6) % 7;

// Клавіатура
const keyboard = [
  [
    {
      text: '◀️',
      callback_data: canGoPrev
        ? 'cal_prev'
        : 'cal_ignore'
    },
    {
      text: `${pad(month)}/${year}`,
      callback_data: 'cal_ignore'
    },
    {
      text: '▶️',
      callback_data: canGoNext
        ? 'cal_next'
        : 'cal_ignore'
    }
  ],
  ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Нд'].map(text => ({
    text,
    callback_data: 'cal_ignore'
  }))
];

let row = [];

// Порожні клітинки
for (let i = 0; i < firstDay; i++) {
  row.push({
    text: ' ',
    callback_data: 'cal_ignore'
  });
}

// Дні календаря
for (let day = 1; day <= daysInMonth; day++) {
  const dateStr = `${year}-${pad(month)}-${pad(day)}`;

  const available =
    dateStr >= earliestDate &&
    dateStr <= maxDate;

  row.push({
    text: String(day),
    callback_data: available
      ? `cal_day_${dateStr}`
      : 'cal_ignore'
  });

  if (row.length === 7) {
    keyboard.push(row);
    row = [];
  }
}

// Останній рядок
if (row.length > 0) {
  while (row.length < 7) {
    row.push({
      text: ' ',
      callback_data: 'cal_ignore'
    });
  }

  keyboard.push(row);
}

return [{
  json: {
    year,
    month,
    earliest_date: earliestDate,
    latest_date: latestDate,
    today,
    calendar_title:
      `📅 Оберіть дату (${pad(month)}/${year}):`,
    calendar_keyboard: keyboard,
    can_go_prev: canGoPrev,
    can_go_next: canGoNext
  }
}];

