const callback = trigger.callback_query || {};
const action = callback.data || '';
const message = callback.message || {};

// Отримуємо місяць із повідомлення Telegram
const text = message.text || message.caption || '';
const match = text.match(/(\d{1,2})\/(\d{4})/);

// Поточна дата за Києвом
const today = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Europe/Kyiv',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

const [currentYear, currentMonth] = today.split('-').map(Number);

let year = match ? Number(match[2]) : currentYear;
let month = match ? Number(match[1]) : currentMonth;

// Перемикання місяців
if (action === 'cal_prev') {
  month--;

  if (month < 1) {
    month = 12;
    year--;
  }
}

if (action === 'cal_next') {
  month++;

  if (month > 12) {
    month = 1;
    year++;
  }
}

