}

const action = match[1];
const startDate = match[2];

let year = Number(match[3]);
let month = Number(match[4]);

// Перемикання місяця
if (action === 'next') {
  month++;
  if (month > 12) {
    month = 1;
    year++;
  }
} else {
  month--;
  if (month < 1) {
    month = 12;
    year--;
  }
}

// Межі календаря
const [startYear, startMonth] = startDate
  .split('-')
  .map(Number);

const now = new Date();
const currentYear = now.getFullYear();
const currentMonth = now.getMonth() + 1;

// Не переходимо раніше початкового місяця
if (
  year < startYear ||
  (year === startYear && month < startMonth)
) {
  year = startYear;
  month = startMonth;
}

// Не переходимо в майбутні місяці
if (
  year > currentYear ||
  (year === currentYear && month > currentMonth)
) {
  year = currentYear;
  month = currentMonth;
}

const daysInMonth = new Date(year, month, 0).getDate();

const firstDay =
  (new Date(year, month - 1, 1).getDay() + 6) % 7;

const keyboard = [
  [
    {
      text: '◀️',
      callback_data:
        `cal_end_prev_${startDate}_${year}-${String(month).padStart(2, '0')}`
    },
    {
      text: `📅 ${String(month).padStart(2, '0')}/${year}`,
      callback_data: 'cal_ignore'
    },
    {
      text: '▶️',
      callback_data:
        `cal_end_next_${startDate}_${year}-${String(month).padStart(2, '0')}`
    }
  ],
  [
    ...['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Нд'].map(text => ({
      text,
      callback_data: 'cal_ignore'
    }))
  ]
];

let row = [];

for (let i = 0; i < firstDay; i++) {
  row.push({
    text: ' ',
    callback_data: 'cal_ignore'
  });
}

const today = [
  now.getFullYear(),
  String(now.getMonth() + 1).padStart(2, '0'),
  String(now.getDate()).padStart(2, '0')
].join('-');

for (let day = 1; day <= daysInMonth; day++) {
  const dateStr =
    `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;

  row.push({
    text: String(day),
    callback_data:
      dateStr < startDate || dateStr > today
        ? 'cal_ignore'
        : `cal_range_${startDate}_${dateStr}`
  });

  if (row.length === 7) {
    keyboard.push(row);
    row = [];
  }
}

if (row.length) {
  while (row.length < 7) {
    row.push({
      text: ' ',
      callback_data: 'cal_ignore'
    });
  }
  keyboard.push(row);
}

// Кнопка «Назад» прибрана

return [{
  json: {
    chat_id: callback.message.chat.id,
    message_id: callback.message.message_id,
    callback_query_id: callback.id,
    calendar_title:
      `📅 Початок: ${startDate.split('-').reverse().join('.')}\n` +
      'Оберіть дату завершення:',
    calendar_keyboard: keyboard
  }
}];

const trigger = $('Telegram Trigger1').first().json;
const callback = trigger.callback_query || {};
const message = callback.message || {};

const today = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Europe/Kyiv',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

// Тимчасові межі історії.
// Початок — підтверджена дата першого CSV.
const earliestDate = '2026-09-01';

// Остання доступна дата обмежується сьогоднішнім днем.
const latestDate = today;

return [{
  json: {
    earliest_date: earliestDate,
    latest_date: latestDate,
    today,
    chat_id: message.chat?.id,
    message_id: message.message_id,
    callback_query_id: callback.id
  }
}];

